import{_ as a,o as t,c,a5 as i}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"FR 3.5.1 - Create Media Package","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-1-create-media-package/spec.md","filePath":"feature/media-package-campaign/3-5-1-create-media-package/spec.md"}'),o={name:"feature/media-package-campaign/3-5-1-create-media-package/spec.md"};function n(s,e,d,l,r,p){return t(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="fr-3-5-1-create-media-package" tabindex="-1">FR 3.5.1 - Create Media Package <a class="header-anchor" href="#fr-3-5-1-create-media-package" aria-label="Permalink to &quot;FR 3.5.1 - Create Media Package&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Status</td><td>Ready for technical review</td></tr><tr><td>Roles</td><td>Admin; Agency Owner; Client</td></tr><tr><td>Delivery task</td><td>DA-E50-01</td></tr></tbody></table><h2 id="outcome" tabindex="-1">Outcome <a class="header-anchor" href="#outcome" aria-label="Permalink to &quot;Outcome&quot;">​</a></h2><p>Admin templates and Agency packages use the same <code>media_packages</code> record. Templates have <code>is_template=true</code> and no agency; selectable packages have <code>is_template=false</code>, belong to one Agency, and may retain their source template ID.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>List template packages with <code>GET /api/v1/media-package-templates</code>.</li><li>All Agencies can view Admin templates (<code>is_template=true</code>, <code>agencyId=null</code>).</li><li>An Agency Owner creates an Agency package with <code>POST /api/v1/agencies/{agencyId}/media-package-custom</code>, either independently or from an optional <code>sourceTemplateId</code>.</li><li>A package provides <code>id</code>, <code>name</code>, <code>type</code>, <code>durationWeeks</code>, <code>budgetAmount</code>, <code>scopeDescription</code>, <code>isTemplate</code>, <code>agencyId</code>, <code>sourceTemplateId</code>, and <code>availableToWorkspaces</code> where applicable.</li><li>Workspace selection is delivered by DA-E50-02 and uses one <code>package_id</code> reference.</li><li>The Agency Media Package screen at <code>/agency/{agencyId}/media-packages</code> is the Owner&#39;s management surface. It lists global templates and persisted Agency packages, supports cloning a template, and lets the Owner hide/show Agency packages.</li><li>Creating an Agency package does not require a Workspace; the resulting package belongs to the Agency catalogue.</li><li>The Workspace Media Package screen lists only packages belonging to that Workspace&#39;s Agency with <code>availableToWorkspaces=true</code>, and exposes selection only to the Client role.</li><li><code>GET /api/v1/agencies/{agencyId}/media-package-custom</code> reloads persisted custom packages for management.</li><li><code>GET /api/v1/workspaces/{workspaceId}/media-packages</code> returns packages available for Client selection.</li><li><code>PATCH /api/v1/agencies/{agencyId}/media-packages/{packageId}/availability</code> changes Agency-wide Workspace visibility.</li><li>The Workspace dashboard prompts the Client to select a package when none has been selected.</li><li>UI copy uses the <code>mediaPackage</code> namespace with key-parallel Vietnamese and English locale files.</li><li>Loading, empty, error, selected, and submitting states work in both light and dark themes using semantic theme tokens.</li></ul><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><ul><li>Only Admin owns global templates; authoring UI is out of scope.</li><li>Global templates are initially supplied by seed data while the Admin stream implements authoring.</li><li>A custom package cannot be exposed as a global template.</li><li>Only the Agency Owner may create packages or change their Workspace visibility.</li><li>Global templates cannot be selected directly by a Workspace.</li><li>Hiding an Agency package affects new selections only; an existing Workspace selection remains readable and negotiable.</li><li>Do not use the obsolete polymorphic <code>packageRefType</code> database model.</li></ul><h2 id="confirmed-selection-notification-scope-—-2026-10-13" tabindex="-1">Confirmed selection notification scope — 2026-10-13 <a class="header-anchor" href="#confirmed-selection-notification-scope-—-2026-10-13" aria-label="Permalink to &quot;Confirmed selection notification scope — 2026-10-13&quot;">​</a></h2><p>Scheduled package-selection reminders are not required. Keep the current Package gate: Client accesses Package negotiation and Chat; Manager also retains Workspace settings. Creative features remain gated until the package is approved. No scheduler or configurable X-day cadence is part of DA-943.</p>',10)])])}const h=a(o,[["render",n]]);export{m as __pageData,h as default};
